- `23.10` On a wide screen the page spans the whole window: the timeline and the calendar stretch edge to edge rather than stopping at a content width.

  🚩 _Behavior leaf._ <!-- req-gallery:23.10 -->

  <details><summary>Notes</summary>

  Measured at 2560 pixels wide: the timeline and the calendar card each run
  from the page's side gutter to the other, and the header's wordmark and
  controls sit on the same edges. The other planner, `/plan/`, keeps its
  content width.
  </details>
''',1)
open(p,'w').write(s)
EOF
cat > product/requirements/behavior/cases/planng-wide.23.10.case.js <<'EOF'
"use strict";
const { jerusalemReady } = require("../../shared/case-helpers");

const WIDE = { width: 2560, height: 1200 };
const GUTTER = 24;

/* Nothing on the page stops at a content width: at 2560 pixels the timeline,
 * the calendar card and the header all reach the side gutters. */
module.exports = {
  description: "on a wide screen the timeline and the calendar span the whole window",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.setViewportSize(WIDE);
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    const edges = await page.evaluate(() => {
      const box = (sel) => {
        const r = document.querySelector(sel).getBoundingClientRect();
        return { left: Math.round(r.left), right: Math.round(r.right) };
      };
      return {
        page: document.documentElement.clientWidth,
        timeline: box("#timeline"),
        calendar: box("#planPanel"),
        header: box(".header-inner"),
      };
    });
    for (const part of ["timeline", "calendar"]) {
      assert.equal(edges[part].left, GUTTER, `the ${part} starts at the left gutter`);
      assert.equal(edges[part].right, edges.page - GUTTER, `the ${part} runs to the right gutter`);
    }
    assert.deepEqual(
      edges.header,
      { left: GUTTER, right: edges.page - GUTTER },
      "the header's contents sit on the same edges"
    );
  },
};
EOF
